    # Sort intervals by end time
    intervals.sort(key=lambda x: x[1])

    # Use binary search to find the latest non-overlapping interval
    def find_last_non_overlapping(end_time):
        # We look for the last interval whose end time is <= current start time
        # Using bisect to find the insertion point
        low, high = 0, len(intervals)
        while low < high:
            mid = (low + high) // 2
            if intervals[mid][1] <= end_time:
                low = mid + 1
            else:
                high = mid
        return low - 1

    count = 0
    last_end = -float('inf')

    for start, end in intervals:
        if start >= last_end:
            count += 1
            last_end = end
