            # Find the latest non-overlapping interval
            idx = find_last_non_overlapping(start)
            if idx >= 0:
                # Replace the current interval with the one that ends latest
                # So that we can have more room for future intervals
                last_end = intervals[idx][1]

    return len(intervals) - count

